const student = $getNode('Obtener Datos Estudiante').json;
const history = $getNode('Obtener Historial').json[0] ? $getNode('Obtener Historial').json[0].messages : [];
const newMessage = { role: 'user', content: $json.body.message };

const studentName = `${student.first_name} ${student.last_name}`;
const placeholder = '[ESTUDIANTE]';

const anonymize = (text) => text.replace(new RegExp(studentName, 'gi'), placeholder);

const anonymizedHistory = history.map(msg => ({ ...msg, content: anonymize(msg.content) }));
const anonymizedNewMessage = { ...newMessage, content: anonymize(newMessage.content) };

return {
  anonymizedHistory,
  anonymizedNewMessage,
  studentName,
  placeholder
};

const assistantResponse = $getNode('OpenAI Chat').json.choices[0].message.content;
const { studentName, placeholder } = $getNode('Anonimizar Conversación').json;

const deanonymizedResponse = assistantResponse.replace(new RegExp(placeholder.replace(/[\[\]]/g, '\\$&'), 'gi'), studentName);

return {
  role: 'assistant',
  content: deanonymizedResponse
};
